const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu');menu.textContent=open?'×':'☰';nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Ouvrir le menu');menu.textContent='☰'}));
const solutions=[{label:'L’INTÉRIEUR RENCONTRE L’EXTÉRIEUR',title:'Plus de lumière.<br>Moins de limites.',description:'Fenêtres et baies coulissantes en aluminium : des lignes épurées pour ouvrir vos espaces et profiter pleinement de chaque perspective.',features:['Design & finesse des profilés','Confort thermique & acoustique','Solutions adaptées à votre projet'],image:'interior.jpg',alt:'Espace de vie avec menuiseries aluminium',number:'01 — OUVRIR LES PERSPECTIVES'},{label:'L’ARCHITECTURE PREND UNE AUTRE DIMENSION',title:'Des façades.<br>Du caractère.',description:'Murs-rideaux et systèmes de façades aluminium pour dessiner l’enveloppe de vos bâtiments et faire dialoguer lumière, matière et architecture.',features:['Liberté de composition','Solutions pour l’enveloppe du bâtiment','Accompagnement technique'],image:'architecture.jpg',alt:'Façade de bâtiment contemporain',number:'02 — DESSINER L’ENVELOPPE'},{label:'LA PREMIÈRE IMPRESSION COMPTE',title:'Une entrée.<br>Votre signature.',description:'Portes intérieures et extérieures : choisissez une solution qui prolonge le caractère de votre architecture et accompagne votre quotidien.',features:['Portes intérieures & extérieures','Esthétique personnalisée','Conseil pour votre projet'],image:'interior.jpg',alt:'Architecture intérieure contemporaine',number:'03 — FAIRE ENTRER LE DESIGN'},{label:'LA LUMIÈRE, À VOTRE MESURE',title:'Apprivoiser le soleil.<br>Savourer l’espace.',description:'Des solutions de protection solaire pour moduler la lumière, créer de l’ombre et penser vos espaces extérieurs dans la continuité de votre habitat.',features:['Maîtrise de la lumière','Confort des espaces de vie','Intégration architecturale'],image:'hero.jpg',alt:'Habitat contemporain ouvert sur une terrasse',number:'04 — RÉINVENTER L’OMBRE'}];
const tabs=[...document.querySelectorAll('[role=tab]')];function selectTab(index){const s=solutions[index];tabs.forEach((b,i)=>{b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1});document.querySelector('#solution-panel').setAttribute('aria-labelledby','tab-'+index);document.querySelector('#solution-label').textContent=s.label;document.querySelector('#solution-title').innerHTML=s.title;document.querySelector('#solution-description').textContent=s.description;document.querySelector('#solution-features').replaceChildren(...s.features.map(f=>{const li=document.createElement('li');li.textContent=f;return li}));const image=document.querySelector('#solution-image');image.src='assets/'+s.image;image.alt=s.alt;document.querySelector('#solution-number').textContent=s.number}tabs.forEach((b,i)=>{b.tabIndex=i===0?0:-1;b.addEventListener('click',()=>selectTab(i));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;else if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else return;e.preventDefault();selectTab(n);tabs[n].focus()})});
// Solid six-face aluminium profiles rendered with CSS 3D transforms.
function bar(parent,x,y,w,h,d){const b=document.createElement('div');b.className='bar';Object.assign(b.style,{left:x+'px',top:y+'px',width:w+'px',height:h+'px'});const faces=[['front',w,h,`translateZ(${d/2}px)`],['back',w,h,`rotateY(180deg) translateZ(${d/2}px)`],['right',d,h,`translateX(${w-d/2}px) rotateY(90deg)`],['left',d,h,`translateX(${-d/2}px) rotateY(90deg)`],['top',w,d,`translateY(${-d/2}px) rotateX(90deg)`],['bottom',w,d,`translateY(${h-d/2}px) rotateX(90deg)`]];faces.forEach(([name,width,height,transform])=>{const f=document.createElement('div');f.className='bar-face bar-'+name;Object.assign(f.style,{width:width+'px',height:height+'px',transform});b.append(f)});parent.append(b)}const outer=document.querySelector('#outer-frame'),sashFrame=document.querySelector('#sash-frame');[[0,0,270,18],[0,322,270,18],[0,18,18,304],[252,18,18,304],[129,18,8,304]].forEach(a=>bar(outer,...a,34));[[0,0,115,12],[0,292,115,12],[0,12,12,280],[103,12,12,280]].forEach(a=>bar(sashFrame,...a,24));
const model=document.querySelector('#window-model'),sash=document.querySelector('#window-sash'),rotation=document.querySelector('#rotation'),angle=document.querySelector('#angle-output'),openButton=document.querySelector('#open-window'),stage=document.querySelector('.studio-stage');let turn=-24,tilt=-8,drag=null;function updateView(){const scale=matchMedia('(max-width:680px)').matches?' scale(.9)':'';model.style.transform=`rotateX(${tilt}deg) rotateY(${turn}deg)${scale}`;rotation.value=turn;angle.textContent=Math.round(turn)+'°'}rotation.addEventListener('input',()=>{turn=Number(rotation.value);updateView()});openButton.addEventListener('click',()=>{const open=!sash.classList.contains('is-open');sash.classList.toggle('is-open',open);openButton.setAttribute('aria-pressed',String(open));openButton.innerHTML=(open?'Fermer la fenêtre':'Ouvrir la fenêtre')+' <span>↗</span>';document.querySelector('#model-status').textContent=open?'Fenêtre ouverte':'Fenêtre fermée'});document.querySelectorAll('.finish').forEach(b=>b.addEventListener('click',()=>{model.style.setProperty('--frame-color',b.dataset.color);document.querySelectorAll('.finish').forEach(f=>{f.classList.toggle('selected',f===b);f.setAttribute('aria-pressed',String(f===b))});document.querySelector('#model-status').textContent='Finition '+b.textContent}));stage.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;drag={x:e.clientX,start:turn};stage.setPointerCapture(e.pointerId)});stage.addEventListener('pointermove',e=>{if(!drag)return;turn=Math.max(-65,Math.min(65,drag.start+(e.clientX-drag.x)*.4));updateView()});stage.addEventListener('pointerup',()=>drag=null);stage.addEventListener('pointercancel',()=>drag=null);document.querySelector('#reset-model').addEventListener('click',()=>{turn=-24;tilt=-8;updateView();if(sash.classList.contains('is-open'))openButton.click();document.querySelector('.finish').click()});window.addEventListener('resize',updateView);
